begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select ok(not has_function_privilege('anon','public.admin_set_duel_qa_v1(uuid[],uuid,text,integer)','EXECUTE'),'anon cannot manage QA');
select ok(not has_function_privilege('authenticated','public.admin_set_duel_qa_v1(uuid[],uuid,text,integer)','EXECUTE'),'member cannot manage QA');
select ok(not has_function_privilege('service_role','public.admin_set_duel_qa_v1(uuid[],uuid,text,integer)','EXECUTE'),'service API cannot manage QA');
select ok(not has_table_privilege('authenticated','private.duel_release_qa_v1','SELECT'),'member cannot inspect QA');
select ok(not has_table_privilege('anon','private.duel_release_qa_v1','SELECT'),'anon cannot inspect QA');
select ok(not has_table_privilege('authenticated','private.duel_release_qa_v1','INSERT'),'member cannot self-enroll');
insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select ('68000000-0000-4000-8000-00000000000'||i)::uuid,'authenticated','authenticated','qa-admit-'||i||'@local.test','{}','{}',now(),now() from generate_series(1,3)i;
insert into public.profiles(id,username,nickname,synthetic_email)
select ('68000000-0000-4000-8000-00000000000'||i)::uuid,'qa_admission_v1_'||i,'QA Admission','qa-admit-'||i||'@local.test' from generate_series(1,3)i;
create temp table qa_test(ids uuid[],request_id uuid,response jsonb);
insert into qa_test values(array['68000000-0000-4000-8000-000000000001','68000000-0000-4000-8000-000000000002']::uuid[],extensions.gen_random_uuid(),null);
select throws_ok($q$select public.admin_set_duel_qa_v1(ids,request_id,'local QA approval') from qa_test$q$,'P0001','QA_GATE_MUST_BE_CLOSED','QA exception requires closed gate and current protocol');
update private.duel_release_control_v1 set entry_open=false,required_protocol='search-authority-v1';
create function pg_temp.qa_missing_control() returns text language plpgsql as $$
declare c record; observed text;
begin select * into strict c from pg_temp.qa_test;
 begin
  delete from private.duel_release_control_v1;
  perform public.admin_set_duel_qa_v1(c.ids,c.request_id,'local QA approval');
  observed:='UNEXPECTED_SUCCESS';raise sqlstate 'ZQ088';
 exception when sqlstate 'ZQ088' then null;when others then observed:=sqlerrm;end;
 return observed;
end; $$;
select is(pg_temp.qa_missing_control(),'QA_GATE_REQUIRED','missing control row fails closed');
select throws_ok($q$select public.admin_set_duel_qa_v1(array['68000000-0000-4000-8000-000000000001','68000000-0000-4000-8000-000000000002','68000000-0000-4000-8000-000000000003']::uuid[],extensions.gen_random_uuid(),'local QA approval')$q$,'P0001','QA_APPROVAL_INVALID','third account rejected');
select throws_ok($q$select public.admin_set_duel_qa_v1(ids,request_id,'local QA approval',7201) from qa_test$q$,'P0001','QA_APPROVAL_INVALID','TTL above two hours rejected');
select throws_ok($q$select public.admin_set_duel_qa_v1(array[ids[1],ids[1]],request_id,'local QA approval') from qa_test$q$,'P0001','QA_APPROVAL_INVALID','duplicate account rejected');
select throws_ok($q$select public.admin_set_duel_qa_v1(array[extensions.gen_random_uuid()],request_id,'local QA approval') from qa_test$q$,'P0001','QA_MEMBER_REQUIRED','nonmember rejected');
update qa_test set response=public.admin_set_duel_qa_v1(ids,request_id,'local QA approval');
select is((select count(*)::int from private.duel_release_qa_v1),2,'exactly two QA accounts');
select ok((select bool_and(expires_at=approved_at+interval '60 minutes') from private.duel_release_qa_v1),'default TTL 60 minutes');
select ok((select response=public.admin_set_duel_qa_v1(ids,request_id,'local QA approval') from qa_test),'retry does not renew TTL');
select throws_ok($q$select public.admin_set_duel_qa_v1(ids,request_id,'changed QA approval') from qa_test$q$,'P0001','QA_REQUEST_CONFLICT','management request conflict rejected');
select set_config('request.jwt.claim.sub','68000000-0000-4000-8000-000000000001',true);
select set_config('request.headers','{}',true);
select throws_ok('select public.create_duel_room_v2(true)','P0001','DUEL_CLIENT_RELOAD_REQUIRED','QA old protocol rejected');
select set_config('request.headers','{"x-wiki-duel-protocol":"search-authority-v1"}',true);
create temp table qa_room(id uuid,code text);
insert into qa_room select id,room_code from public.create_discoverable_duel_room_v1(true,false);
select is((select count(*)::int from qa_room),1,'QA A normal UI wrapper create');
select set_config('request.jwt.claim.sub','68000000-0000-4000-8000-000000000003',true);
select throws_ok('select public.create_duel_room_v2(true)','P0001','DUEL_ENTRY_PAUSED','ordinary current member cannot create');
select throws_ok($q$select public.join_duel_room_v2(code) from qa_room$q$,'P0001','DUEL_ENTRY_PAUSED','ordinary member cannot join QA');
select set_config('request.jwt.claim.sub','68000000-0000-4000-8000-000000000002',true);
select lives_ok($q$select public.join_duel_room_v2(code) from qa_room$q$,'QA B normal join');
select throws_ok($q$select public.start_duel_room_v2(id,'QA','qa','rev') from qa_room$q$,'P0001','HOST_REQUIRED','QA does not become host');
insert into public.wiki_pages(page_id,canonical_title) values('qa-admit-start','QA Admit Start'),('qa-admit-target','QA Admit Target');
insert into public.wiki_page_snapshots(page_id,revision_id,canonical_title_snapshot) values('qa-admit-start','qa-admit-rev','QA Admit Start'),('qa-admit-target','qa-admit-target-rev','QA Admit Target');
select set_config('request.jwt.claim.sub','68000000-0000-4000-8000-000000000001',true);
select public.set_duel_target_v2(id,'QA Admit Target','qa-admit-target','qa-admit-target-rev',false) from qa_room;
select lives_ok($q$select public.start_duel_room_v2(id,'QA Admit Start','qa-admit-start','qa-admit-rev') from qa_room$q$,'QA host normal start');
update private.duel_release_qa_v1 set approved_at=clock_timestamp()-interval '2 hours',expires_at=clock_timestamp()-interval '1 second';
select throws_ok('select public.create_duel_room_v2(true)','P0001','DUEL_ENTRY_PAUSED','expired QA denied new entry');
select lives_ok($q$select public.initialize_duel_player_v2(id,'QA Admit Start','qa-admit-start','qa-admit-rev') from qa_room$q$,'expired QA initializes already started game');
select public.admin_set_duel_qa_v1('{}',extensions.gen_random_uuid(),'local QA revocation');
select is((select count(*)::int from private.duel_release_qa_v1),0,'QA revocation removes exception');
select set_config('request.jwt.claim.sub','68000000-0000-4000-8000-000000000002',true);
select lives_ok($q$select public.initialize_duel_player_v2(id,'QA Admit Start','qa-admit-start','qa-admit-rev') from qa_room$q$,'revoked QA initializes existing game');
select lives_ok($q$select public.heartbeat_duel_v2(id) from qa_room$q$,'revoked QA keeps heartbeat');
select lives_ok($q$select public.leave_duel_room_v2(id,extensions.gen_random_uuid()) from qa_room$q$,'revoked QA normal retire and XP settlement');
select is((select status from public.game_rooms where id=(select id from qa_room)),'finished','QA game settles under closed gate');
select throws_ok('select public.create_duel_room_v2(true)','P0001','DUEL_ENTRY_PAUSED','revoked QA cannot create');
update private.duel_release_control_v1 set entry_open=true;
select set_config('request.jwt.claim.sub','68000000-0000-4000-8000-000000000003',true);
select lives_ok('select public.create_duel_room_v2(true)','ordinary current member admitted only after reopening');
select set_config('request.headers','{}',true);
select throws_ok('select public.create_duel_room_v2(true)','P0001','DUEL_CLIENT_RELOAD_REQUIRED','old tab remains denied after reopening');
select * from finish();
rollback;
